// Программа для мигания встроенным светодиодом

void setup() {
  // Настраиваем пин встроенного светодиода как выход
  pinMode(LED_BUILTIN, OUTPUT);  // LED_BUILTIN — специальная константа, которая автоматически подставляет правильный номер пина для вашей платы
}

void loop() {
  digitalWrite(LED_BUILTIN, HIGH);  // Включаем светодиод (подаём высокий уровень)
  delay(1000);                        // Ждём 1 секунду
  digitalWrite(LED_BUILTIN, LOW);   // Выключаем светодиод (подаём низкий уровень)
  delay(1000);                        // Ждём ещё 1 секунду
}
